import { gzipSync, gunzipSync } from 'node:zlib';
import { createDatabasePage, flatten, queryDatabase, updatePageProperties } from './notion.mjs';

const MAX_RICH_TEXT_CHUNK = 1900;
const MAX_RICH_TEXT_ITEMS = 100;
const MAX_PAYLOAD_LENGTH = MAX_RICH_TEXT_CHUNK * MAX_RICH_TEXT_ITEMS;
const SNAPSHOT_PREFIX = 'dashboard-snapshot:';

function pick(source, keys) {
  return Object.fromEntries(keys.map(key => [key, source?.[key]]));
}

function textObjects(value, maxItems = MAX_RICH_TEXT_ITEMS) {
  const text = String(value || '');
  const parts = [];
  for (let index = 0; index < text.length && parts.length < maxItems; index += MAX_RICH_TEXT_CHUNK) {
    parts.push({ type: 'text', text: { content: text.slice(index, index + MAX_RICH_TEXT_CHUNK) } });
  }
  return parts;
}

function title(value) {
  return { title: textObjects(value, 1) };
}

function richText(value) {
  return { rich_text: textObjects(value) };
}

function date(value) {
  return { date: value ? { start: value } : null };
}

function snapshotDate(dashboard) {
  return String(dashboard.generatedAt || new Date().toISOString()).slice(0, 10);
}

function snapshotRunId(dashboard) {
  return `${SNAPSHOT_PREFIX}${snapshotDate(dashboard)}`;
}

function compactWorkItem(item) {
  return pick(item, [
    'id', 'url', 'title', 'status', 'team', 'assignees', 'project', 'start', 'due', 'completedAt',
    'sprint', 'branch', 'specId', 'spec', 'notionUpdatedAt', 'latestGitAt', 'overdueDays',
    'staleBusinessDays', 'riskScore', 'guideStatus', 'itemLevel', 'sprintRelation',
  ]);
}

function compactIssue(issue) {
  const metadata = issue.metadata ? {
    url: issue.metadata.url,
    remote: issue.metadata.remote,
    commitHash: issue.metadata.commitHash,
    representativeCommit: issue.metadata.representativeCommit?.url
      ? { url: issue.metadata.representativeCommit.url }
      : undefined,
  } : undefined;
  return {
    ...pick(issue, [
      'id', 'detectedAt', 'category', 'label', 'responsibleRole', 'actionTarget',
      'recommendedAction', 'project', 'workItemId', 'specId', 'type', 'severity', 'message',
    ]),
    metadata,
  };
}

function compactProject(project) {
  return {
    ...pick(project, ['name', 'gitUrl', 'goal', 'milestones', 'notionSummary', 'stats', 'recentGitAt', 'nearestDue', 'teams']),
    currentSprints: project.currentSprints ?? project.config?.currentSprints ?? [],
    sprintRequired: project.sprintRequired ?? project.config?.sprintRequired,
    notionId: project.notionId || project.config?.notionId,
    config: project.config ? pick(project.config, ['gitUrl', 'notionId', 'currentSprints', 'sprintRequired', 'sprintSettingSource', 'sprintSettingRevision']) : undefined,
    specs: (project.specs || []).map(spec => ({
      ...pick(spec, ['id', 'url', 'title', 'status', 'parentStatus', 'childDerivedStatus', 'completionMismatch', 'sprint', 'start', 'due', 'core', 'owners', 'targetAt', 'childStats']),
      tasks: (spec.tasks || []).map(compactWorkItem),
    })),
    specInsights: (project.specInsights || []).map(insight => ({
      ...pick(insight, ['specId', 'title', 'summary', 'blockers', 'nextAction']),
      evidence: (insight.evidence || []).slice(0, 5).map(item => pick(item, [
        'source', 'timestamp', 'title', 'excerpt', 'url', 'attention', 'attentionType', 'evidenceRole',
      ])),
    })),
    projectOperations: project.projectOperations ? {
      ...pick(project.projectOperations, ['source', 'evidenceCount', 'latestLifecycleSignal', 'latestBuild', 'latestQa', 'latestRelease', 'latestData']),
      evidence: (project.projectOperations.evidence || []).slice(0, 4).map(item => pick(item, [
        'source', 'timestamp', 'title', 'excerpt', 'url', 'attention', 'attentionType', 'attentionAction', 'evidenceRole',
      ])),
    } : null,
  };
}

function compactPerson(person) {
  return {
    ...pick(person, [
      'name', 'teams', 'projects', 'projectCount', 'count', 'inProgressCount', 'overdueCount',
      'missingCompletedCount', 'nearestDue', 'latestGitAt',
    ]),
    tasks: (person.tasks || []).map(task => ({ id: task.id })),
  };
}

function compactGit(git = {}) {
  return {
    repositories: git.repositories || [],
    commits: (git.commits || []).slice(0, 100).map(commit => pick(commit, [
      'hash', 'shortHash', 'committedAt', 'author', 'message', 'repository', 'project',
      'workItemId', 'branch', 'url',
    ])),
    errors: git.errors || [],
  };
}

export function compactDashboard(dashboard) {
  return {
    ...pick(dashboard, [
      'generatedAt', 'dashboardUrl', 'sample', 'errors', 'metrics', 'deltas', 'ai',
      'sourceHealth', 'notionSetup', 'snapshotComparison', 'agentHandoff', 'remoteSnapshot', 'summarySyncedAt', 'sprintScope',
    ]),
    projects: (dashboard.projects || []).map(compactProject),
    workItems: (dashboard.workItems || []).map(compactWorkItem),
    guideViolationItems: (dashboard.guideViolationItems || []).map(item => ({
      ...compactWorkItem(item),
      issues: (item.issues || []).map(compactIssue),
    })),
    progressSetupItems: (dashboard.progressSetupItems || []).map(item => ({
      ...compactWorkItem(item),
      issues: (item.issues || []).map(compactIssue),
    })),
    workload: (dashboard.workload || []).map(compactPerson),
    validationIssues: (dashboard.validationIssues || []).map(compactIssue),
    git: compactGit(dashboard.git),
  };
}

export function encodeDashboardSnapshot(dashboard) {
  return gzipSync(JSON.stringify(compactDashboard(dashboard))).toString('base64');
}

export function decodeDashboardSnapshot(payload) {
  return JSON.parse(gunzipSync(Buffer.from(String(payload || ''), 'base64')).toString('utf8'));
}

function propertiesFor(dashboard, payload) {
  const day = snapshotDate(dashboard);
  return {
    이름: title(`대시보드 스냅샷 / ${day}`),
    프로젝트명: richText('대시보드 스냅샷'),
    기준일: date(day),
    run_id: richText(snapshotRunId(dashboard)),
    '현재 진행 요약': richText('대시보드 웹 표시용 압축 스냅샷 (gzip+base64)'),
    payload: richText(payload),
  };
}

export async function publishDashboardSnapshotToNotion({
  databaseId,
  dashboard,
  query = queryDatabase,
  create = createDatabasePage,
  update = updatePageProperties,
}) {
  const payload = encodeDashboardSnapshot(dashboard);
  if (payload.length > MAX_PAYLOAD_LENGTH) {
    throw new Error(`대시보드 스냅샷이 Notion payload 한도(${MAX_PAYLOAD_LENGTH}자)를 초과했습니다: ${payload.length}자`);
  }
  const runId = snapshotRunId(dashboard);
  const rows = await query(databaseId, { property: 'run_id', rich_text: { equals: runId } });
  const properties = propertiesFor(dashboard, payload);
  if (rows[0]) {
    await update(rows[0].id, properties);
    return { status: 'updated', pageId: rows[0].id, runId, bytes: payload.length };
  }
  const page = await create(databaseId, properties);
  return { status: 'created', pageId: page.id, runId, bytes: payload.length };
}

export async function readLatestDashboardSnapshotFromNotion({ databaseId, query = queryDatabase }) {
  const pages = await query(
    databaseId,
    { property: 'run_id', rich_text: { starts_with: SNAPSHOT_PREFIX } },
    [{ property: '기준일', direction: 'descending' }],
  );
  if (!pages[0]) return null;
  const row = flatten(pages[0]);
  if (!row.payload) return null;
  return {
    dashboard: decodeDashboardSnapshot(row.payload),
    pageId: row._id,
    runId: row.run_id,
    updatedAt: row._edited,
  };
}

export const DASHBOARD_SNAPSHOT_MAX_PAYLOAD_LENGTH = MAX_PAYLOAD_LENGTH;

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));

export function loadEnv() {
  const envPath = path.join(ROOT, '.env');
  if (!fs.existsSync(envPath)) return;
  for (const line of fs.readFileSync(envPath, 'utf8').split('\n')) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, '');
  }
}

export function loadConfig() {
  return JSON.parse(fs.readFileSync(path.join(ROOT, 'config.json'), 'utf8'));
}

const RESOLVED_PATTERN = /(?:해결|해소|복구|정상화)(?:됐|되었|함|완료)|(?:수정|조치|반영)\s*완료|(?:지연|문제|이슈|병목)\s*해소/;

const ATTENTION_RULES = [
  {
    type: 'dependency',
    pattern: /(?:승인|결정|확정)(?:을|를|이|가)?\s*대기|(?:승인|결정|확정).{0,8}(?:없어|안 돼|되지 않아|미완료).{0,16}(?:착수|진행|제작|개발|배포).{0,8}(?:불가|중단|지연|대기)|(?:착수|진행|제작|개발|배포)(?:은|는|이|가)?\s*(?:[\p{L}]+\s*){0,3}(?:승인|결정|확정)\s*대기|(?:작업|착수|진행|제작|개발|배포).{0,8}(?:전|위해).{0,16}(?:승인|결정|확정).{0,8}필요|선행.{0,12}(?:완료|확정|승인).{0,12}(?:필요|대기)|(?:대기|미제공|미전달).{0,12}(?:때문|으로|라서).{0,12}(?:중단|불가|못|지연)|(?:착수|진행|배포).{0,10}(?:대기|불가|중단)/u,
    action: '선행 조건의 담당·완료 기준을 확정하고, 대기 중인 후속 작업의 착수 가능 시점을 확인합니다.',
  },
  {
    type: 'schedule',
    pattern: /(?:일정|납기|마감|기한|제작|개발|검토|전달|배포).{0,12}지연|지연.{0,16}(?:일정|납기|마감|작업|제작|개발|검토|전달|배포|후속)|일정.{0,16}(?:영향|변경|밀림|차질)|(?:납기|마감|기한).{0,12}(?:초과|변경|불가)|(?:예정|일정).{0,8}보다.{0,8}(?:늦|밀)/,
    action: '변경 일정·영향 작업·완료 기준을 확인하고 후속 일정에 반영합니다.',
  },
  {
    type: 'scope',
    pattern: /(?:범위|요구사항|정책|기획|사양|스펙).{0,12}(?:미확정|변경 필요|결정 필요|충돌)|(?:미확정|결정되지).{0,12}(?:범위|요구사항|정책|방향)|방향.{0,8}(?:미정|결정 필요)/,
    action: '미확정 범위의 결정 주체·확정 기준을 정하고, 영향받는 작업에 같은 기준을 반영합니다.',
  },
  {
    type: 'quality',
    pattern: /반복.{0,10}(?:피드백|실패|오류|수정)|(?:검증|qa|테스트).{0,10}(?:반복.{0,6})?(?:실패|불통과)|재작업|재검증.{0,8}필요|품질.{0,8}(?:미달|문제)/i,
    action: '반복 이슈의 재현 조건·수정 담당·통과 기준을 정하고 재검증합니다.',
  },
  {
    type: 'handoff',
    pattern: /협업.{0,16}(?:개선|변경|조정|필요|문제)|(?:전달|공유|인수인계).{0,12}(?:지연|누락|대기|필요|안 됨)|파트.{0,12}(?:전달|대기|협업).{0,10}(?:문제|지연|필요)/,
    action: '필요 산출물의 전달 주체·수신자·완료 기준을 정해 다음 파트가 착수 가능한 상태로 만듭니다.',
  },
  {
    type: 'technical',
    pattern: /(?:빌드|연동|배포|브랜치|머지|api|서버|클라이언트).{0,12}(?:실패|장애|중단|불가|충돌)|(?:빌드|연동|배포|브랜치|머지|api|서버|클라이언트).{0,12}오류(?:로| 때문에|으로).{0,12}(?:실패|불가|중단|차단|지연)|(?:권한|접근|인증).{0,12}(?:실패|없음|불가|오류)/i,
    action: '기술 문제의 재현 조건·해결 담당·복구 기준을 확인하고 차단된 작업의 재개 시점을 정합니다.',
  },
];

export function classifyExecutionAttention(value) {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  if (!text || RESOLVED_PATTERN.test(text)) return null;
  const rule = ATTENTION_RULES.find(candidate => candidate.pattern.test(text));
  return rule ? { type: rule.type, action: rule.action } : null;
}

export function createExpiringCache({ ttlMs = 60_000, now = () => Date.now() } = {}) {
  let value = null;
  let expiresAt = 0;

  return {
    get() {
      return value && now() < expiresAt ? value : null;
    },
    set(next) {
      value = next;
      expiresAt = now() + ttlMs;
      return next;
    },
    clear() {
      value = null;
      expiresAt = 0;
    },
  };
}

import { execFileSync } from 'node:child_process';
import { findTaskForCommit, matchBranches } from './git-branch-matching.mjs';
export { collectGitHubActivity } from './github-activity.mjs';

function git(repositoryPath, args) {
  return execFileSync('git', ['-C', repositoryPath, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
}

function commitUrl(remote, hash) {
  if (!remote) return null;
  const https = remote
    .replace(/^git@github\.com:/, 'https://github.com/')
    .replace(/\.git$/, '');
  return /^https?:\/\//.test(https) ? `${https}/commit/${hash}` : null;
}

function parseLog(output, repository, tasks, remote, branch) {
  if (!output) return [];
  return output.split('\x1e').filter(Boolean).map(record => {
    const [header, ...fileLines] = record.trim().split('\n');
    const [hash, committedAt, author, email, message] = header.split('\x1f');
    const workItem = findTaskForCommit(tasks, repository.project, message, branch);
    return {
      hash,
      shortHash: hash.slice(0, 8),
      committedAt,
      author,
      email,
      message,
      files: fileLines.map(file => file.trim()).filter(Boolean),
      repository: repository.name || repository.path,
      project: repository.project || null,
      workItemId: workItem?.id || null,
      branch,
      url: commitUrl(repository.url || remote, hash),
    };
  });
}

function localBranches(repositoryPath) {
  const output = git(repositoryPath, [
    'for-each-ref',
    '--format=%(refname:short)',
    'refs/heads',
    'refs/remotes/origin',
  ]);
  const byName = new Map();
  for (const ref of output.split('\n').map(value => value.trim()).filter(Boolean)) {
    if (ref === 'origin/HEAD') continue;
    const name = ref.replace(/^origin\//, '');
    if (!byName.has(name) || !ref.startsWith('origin/')) byName.set(name, ref);
  }
  return byName;
}

export function collectGitActivity({ repositories = [], tasks = [], sinceDays = 30, now = () => new Date() }) {
  const result = { repositories: [], commits: [], errors: [] };
  const lastFetchedAt = now().toISOString();
  for (const repository of repositories) {
    try {
      const branch = git(repository.path, ['rev-parse', '--abbrev-ref', 'HEAD']);
      let remote = null;
      try { remote = git(repository.path, ['remote', 'get-url', 'origin']); } catch { /* optional */ }
      const requestedBranches = [...new Set(tasks
        .filter(task => task.project === repository.project && task.branch)
        .map(task => String(task.branch).trim())
        .filter(Boolean))];
      const branchesByName = localBranches(repository.path);
      const branchSelection = matchBranches(requestedBranches, [...branchesByName.keys()]);
      const matchedBranches = [...new Set(branchSelection.matches.map(match => match.actual))];
      const refs = new Map([[branch, branchesByName.get(branch) || branch]]);
      for (const matchedBranch of matchedBranches) refs.set(matchedBranch, branchesByName.get(matchedBranch) || matchedBranch);

      const commitsByHash = new Map();
      let branchFailures = 0;
      for (const [branchName, ref] of refs) {
        try {
          const output = git(repository.path, [
            'log',
            ref,
            `--since=${sinceDays} days ago`,
            '--date=iso-strict',
            '--pretty=format:%x1e%H%x1f%aI%x1f%an%x1f%ae%x1f%s',
            '--name-only',
          ]);
          for (const commit of parseLog(output, repository, tasks, remote, branchName)) {
            if (!commitsByHash.has(commit.hash)) commitsByHash.set(commit.hash, commit);
          }
        } catch {
          branchFailures += 1;
        }
      }
      const commits = [...commitsByHash.values()]
        .sort((left, right) => (right.committedAt || '').localeCompare(left.committedAt || ''));
      const partial = branchFailures || branchSelection.unmatched.length;
      result.repositories.push({
        name: repository.name || repository.path,
        path: repository.path,
        project: repository.project || null,
        source: repository.source || 'config',
        status: partial ? 'partial' : commits.length ? 'ok' : 'no-activity',
        defaultBranch: branch,
        branch,
        remote: repository.url || remote,
        latestCommitAt: commits[0]?.committedAt || null,
        lastFetchedAt,
        commitCount: commits.length,
        mappedCommitCount: commits.filter(commit => commit.workItemId).length,
        ...(requestedBranches.length ? {
          requestedBranches,
          matchedBranches,
          unmatchedBranches: branchSelection.unmatched,
          branchMatches: branchSelection.matches
            .map(({ requested, actual, matchType }) => ({ requested, actual, matchType })),
        } : {}),
      });
      result.commits.push(...commits);
      if (partial) {
        result.errors.push(`Git ${repository.name || repository.path}: partial activity data`);
        if (branchSelection.unmatched.length) {
          result.errors.push(`Git ${repository.name || repository.path}: branch not found: ${branchSelection.unmatched.join(', ')}`);
        }
        if (branchFailures) result.errors.push(`Git ${repository.name || repository.path}: ${branchFailures} branch logs unavailable`);
      }
    } catch (error) {
      result.errors.push(`Git ${repository.name || repository.path}: ${error.message}`);
    }
  }
  result.commits.sort((left, right) => right.committedAt.localeCompare(left.committedAt));
  return result;
}

const COMMON_PREFIX = /^(?:feature|feat|fix|bugfix|hotfix|release|task|work|chore)\//i;

function clean(value) {
  return String(value || '').trim().replace(/^refs\/heads\//i, '').replace(/^origin\//i, '');
}

function comparable(value) {
  return clean(value).toLowerCase();
}

function compact(value) {
  return comparable(value).replace(COMMON_PREFIX, '').replace(/[^a-z0-9가-힣]+/g, '');
}

function tokens(value) {
  return new Set(comparable(value).replace(COMMON_PREFIX, '').split(/[^a-z0-9가-힣]+/).filter(Boolean));
}

function levenshtein(left, right) {
  const previous = Array.from({ length: right.length + 1 }, (_, index) => index);
  for (let leftIndex = 0; leftIndex < left.length; leftIndex += 1) {
    let diagonal = previous[0];
    previous[0] = leftIndex + 1;
    for (let rightIndex = 0; rightIndex < right.length; rightIndex += 1) {
      const above = previous[rightIndex + 1];
      previous[rightIndex + 1] = Math.min(
        previous[rightIndex + 1] + 1,
        previous[rightIndex] + 1,
        diagonal + (left[leftIndex] === right[rightIndex] ? 0 : 1),
      );
      diagonal = above;
    }
  }
  return previous[right.length];
}

export function branchMatchScore(requested, candidate) {
  const requestedName = clean(requested);
  const candidateName = clean(candidate);
  if (!requestedName || !candidateName) return 0;
  if (requestedName === candidateName) return 1;
  if (requestedName.toLowerCase() === candidateName.toLowerCase()) return 0.995;

  const requestedCompact = compact(requestedName);
  const candidateCompact = compact(candidateName);
  if (!requestedCompact || !candidateCompact) return 0;
  if (requestedCompact === candidateCompact) return 0.98;
  if (Math.min(requestedCompact.length, candidateCompact.length) < 5) return 0;

  const shorter = requestedCompact.length <= candidateCompact.length ? requestedCompact : candidateCompact;
  const longer = requestedCompact.length > candidateCompact.length ? requestedCompact : candidateCompact;
  const lengthRatio = shorter.length / longer.length;
  if (longer.includes(shorter) && lengthRatio >= 0.55) return 0.9 + (lengthRatio * 0.05);

  const distance = levenshtein(requestedCompact, candidateCompact);
  const editSimilarity = 1 - (distance / Math.max(requestedCompact.length, candidateCompact.length));
  if (editSimilarity >= 0.84) return editSimilarity;

  const requestedTokens = tokens(requestedName);
  const candidateTokens = tokens(candidateName);
  const intersection = [...requestedTokens].filter(token => candidateTokens.has(token)).length;
  const union = new Set([...requestedTokens, ...candidateTokens]).size;
  const tokenSimilarity = union ? intersection / union : 0;
  return tokenSimilarity >= 0.75 ? 0.84 + (tokenSimilarity * 0.05) : 0;
}

export function matchBranches(requestedBranches, availableBranches, { maxMatchesPerRequest = 3 } = {}) {
  const available = [...new Set(availableBranches.map(clean).filter(Boolean))];
  const matches = [];
  const unmatched = [];

  for (const requested of [...new Set(requestedBranches.map(clean).filter(Boolean))]) {
    const ranked = available
      .map(actual => ({ requested, actual, score: branchMatchScore(requested, actual) }))
      .filter(item => item.score >= 0.84)
      .sort((left, right) => right.score - left.score || left.actual.localeCompare(right.actual));
    if (!ranked.length) {
      unmatched.push(requested);
      continue;
    }

    const exact = ranked.find(item => item.score >= 0.995);
    if (exact) {
      matches.push({ ...exact, matchType: exact.score === 1 ? 'exact' : 'case-insensitive' });
      continue;
    }

    const bestScore = ranked[0].score;
    for (const item of ranked.filter(candidate => candidate.score >= bestScore - 0.02).slice(0, maxMatchesPerRequest)) {
      matches.push({ ...item, matchType: item.score >= 0.98 ? 'normalized' : 'similar' });
    }
  }

  return { matches, unmatched };
}

export function findTaskForCommit(tasks, project, message, branch) {
  const projectTasks = tasks.filter(task => task.project === project);
  const messageMatch = projectTasks.find(task => (
    (task.gitKey && message.includes(task.gitKey)) || message.includes(task.id)
  ));
  if (messageMatch) return messageMatch;
  if (!branch) return null;

  const ranked = projectTasks
    .filter(task => task.branch)
    .map(task => ({ task, score: branchMatchScore(task.branch, branch) }))
    .filter(item => item.score >= 0.84)
    .sort((left, right) => right.score - left.score);
  if (!ranked.length) return null;
  if (ranked[1] && ranked[0].score === ranked[1].score) return null;
  return ranked[0].task;
}

import path from 'node:path';

export function resolveGitRepositories({ projects, configured = [], root }) {
  const overrides = new Map(configured.map(repository => [repository.project, repository]));
  const local = [];
  const remote = [];

  for (const project of projects) {
    const override = overrides.get(project.name);
    if (override?.path) {
      local.push({
        ...override,
        path: path.isAbsolute(override.path) ? override.path : path.resolve(root, override.path),
      });
      continue;
    }
    remote.push({
      name: override?.name || project.name,
      project: project.name,
      url: override?.url || override?.gitUrl || project.gitUrl || null,
      ...(override?.source ? { source: override.source } : {}),
    });
  }

  return { local, remote };
}

import { execFileSync } from 'node:child_process';
import { findTaskForCommit, matchBranches } from './git-branch-matching.mjs';

const API_ROOT = 'https://api.github.com';
const BRANCH_COMMITS_PER_PAGE = 25;
const MAX_TASK_BRANCHES = 20;

function localGitHubToken() {
  return execFileSync('gh', ['auth', 'token'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim();
}

function githubRepository(value) {
  if (!value) return null;
  const ssh = value.match(/^git@github\.com:([^/]+)\/([^/]+?)(?:\.git)?$/);
  if (ssh) return { owner: ssh[1], repo: ssh[2] };
  try {
    const url = new URL(value);
    if (!['github.com', 'www.github.com'].includes(url.hostname)) return null;
    const [owner, rawRepo, ...rest] = url.pathname.split('/').filter(Boolean);
    if (!owner || !rawRepo || rest.length) return null;
    return { owner, repo: rawRepo.replace(/\.git$/, '') };
  } catch {
    return null;
  }
}

async function api(fetchImpl, path, token) {
  try {
    const response = await fetchImpl(`${API_ROOT}${path}`, {
      headers: {
        Accept: 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
        'User-Agent': 'molip-work-status-dashboard',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
    });
    const data = await response.json();
    const nextUrl = response.headers.get('link')?.match(/<([^>]+)>;\s*rel="next"/)?.[1] || null;
    const nextPath = nextUrl ? `${new URL(nextUrl).pathname}${new URL(nextUrl).search}` : null;
    return { ok: response.ok, status: response.status, data, nextPath };
  } catch (error) {
    return { ok: false, status: 0, data: { message: error instanceof Error ? error.message : String(error) } };
  }
}

async function paginatedApi(fetchImpl, path, token, maxPages = 5) {
  const data = [];
  let nextPath = path;
  let pages = 0;
  while (nextPath && pages < maxPages) {
    const page = await api(fetchImpl, nextPath, token);
    if (!page.ok || !Array.isArray(page.data)) return page;
    data.push(...page.data);
    nextPath = page.nextPath;
    pages += 1;
  }
  return { ok: true, status: 200, data, truncated: Boolean(nextPath) };
}

function commitRecord(payload, repository, fullName, branch, tasks) {
  const message = payload.commit?.message?.split('\n')[0] || '';
  const workItem = findTaskForCommit(tasks, repository.project, message, branch);
  return {
    hash: payload.sha,
    shortHash: payload.sha.slice(0, 8),
    committedAt: payload.commit?.author?.date || null,
    author: payload.author?.login || payload.commit?.author?.name || null,
    email: payload.commit?.author?.email || null,
    message,
    files: (payload.files || []).map(file => file.filename).filter(Boolean),
    repository: fullName,
    project: repository.project || null,
    workItemId: workItem?.id || null,
    branch,
    url: payload.html_url || `https://github.com/${fullName}/commit/${payload.sha}`,
  };
}

function requestedTaskBranches(tasks, repository) {
  return [...new Set(tasks
    .filter(task => task.project === repository.project && task.branch)
    .map(task => String(task.branch).trim())
    .filter(Boolean))];
}

function addCandidate(candidates, sha, branch, payload) {
  if (!sha) return;
  const current = candidates.get(sha);
  if (!current) {
    candidates.set(sha, { branch, payload: payload || null });
    return;
  }
  if (!current.payload && payload) current.payload = payload;
  if (!current.branch && branch) current.branch = branch;
}

function failureStatus(status) {
  if (status === 401 || status === 403) return 'auth-required';
  if (status === 404) return 'not-accessible';
  if (status === 422) return 'invalid-url';
  return 'failed';
}

function failureRepository(repository, status, fetchedAt) {
  return {
    name: repository.name || repository.gitUrl || repository.url || 'GitHub',
    project: repository.project || null,
    source: repository.source || 'notion',
    status,
    defaultBranch: null,
    branch: null,
    remote: repository.gitUrl || repository.url || null,
    latestCommitAt: null,
    lastFetchedAt: fetchedAt,
    commitCount: 0,
    mappedCommitCount: 0,
  };
}

export async function collectGitHubActivity({
  repositories = [],
  tasks = [],
  sinceDays = 30,
  fetchImpl = globalThis.fetch,
  token,
  env = process.env,
  ghTokenProvider = localGitHubToken,
  now = () => new Date(),
} = {}) {
  const fetchedAt = now();
  const lastFetchedAt = fetchedAt.toISOString();
  const since = new Date(fetchedAt.getTime() - sinceDays * 86_400_000).toISOString();
  let authorization = env.GITHUB_TOKEN || token || '';
  if (!authorization) {
    try { authorization = await ghTokenProvider(); } catch { authorization = ''; }
  }

  const result = { repositories: [], commits: [], errors: [] };
  for (const repository of repositories) {
    const parsed = githubRepository(repository.gitUrl || repository.url);
    if (!parsed) {
      result.repositories.push(failureRepository(repository, repository.gitUrl || repository.url ? 'invalid-url' : 'missing-url', lastFetchedAt));
      result.errors.push(`GitHub ${repository.project || repository.name || 'repository'}: invalid or missing URL`);
      continue;
    }

    const basePath = `/repos/${encodeURIComponent(parsed.owner)}/${encodeURIComponent(parsed.repo)}`;
    const metadata = await api(fetchImpl, basePath, authorization);
    if (!metadata.ok) {
      const status = failureStatus(metadata.status);
      result.repositories.push(failureRepository(repository, status, lastFetchedAt));
      result.errors.push(`GitHub ${parsed.owner}/${parsed.repo}: ${metadata.data?.message || status}`);
      continue;
    }

    const fullName = metadata.data.full_name || `${parsed.owner}/${parsed.repo}`;
    const defaultBranch = metadata.data.default_branch;
    const requestedBranches = requestedTaskBranches(tasks, repository);
    const [defaultCommits, events, pulls, branchCatalog] = await Promise.all([
      api(fetchImpl, `${basePath}/commits?sha=${encodeURIComponent(defaultBranch)}&since=${encodeURIComponent(since)}&per_page=100`, authorization),
      api(fetchImpl, `${basePath}/events?per_page=100`, authorization),
      api(fetchImpl, `${basePath}/pulls?state=open&sort=updated&direction=desc&per_page=100`, authorization),
      requestedBranches.length
        ? paginatedApi(fetchImpl, `${basePath}/branches?per_page=100`, authorization)
        : Promise.resolve({ ok: true, status: 200, data: [] }),
    ]);

    const availableBranches = branchCatalog.ok && Array.isArray(branchCatalog.data)
      ? branchCatalog.data.map(branch => branch.name).filter(Boolean)
      : [];
    const branchSelection = branchCatalog.ok
      ? matchBranches(requestedBranches, availableBranches)
      : { matches: [], unmatched: requestedBranches };
    const matchedBranches = [...new Set(branchSelection.matches.map(match => match.actual))];
    const limitedBranches = matchedBranches.slice(0, MAX_TASK_BRANCHES);
    const branchFetches = await Promise.all(limitedBranches
      .filter(branch => branch !== defaultBranch)
      .map(async branch => ({
        branch,
        response: await api(
          fetchImpl,
          `${basePath}/commits?sha=${encodeURIComponent(branch)}&since=${encodeURIComponent(since)}&per_page=${BRANCH_COMMITS_PER_PAGE}`,
          authorization,
        ),
      })));
    const sources = [defaultCommits, events, pulls, ...branchFetches.map(fetch => fetch.response)];
    const failedSources = sources.filter(source => !source.ok);
    if (failedSources.length === sources.length) {
      result.repositories.push(failureRepository(repository, 'failed', lastFetchedAt));
      result.errors.push(`GitHub ${fullName}: activity endpoints failed`);
      continue;
    }

    const candidates = new Map();
    if (defaultCommits.ok && Array.isArray(defaultCommits.data)) {
      for (const item of defaultCommits.data) addCandidate(candidates, item.sha, defaultBranch, item);
    }
    if (events.ok && Array.isArray(events.data)) {
      for (const event of events.data) {
        if (event.type !== 'PushEvent' || !event.payload?.head || event.created_at < since) continue;
        const branch = event.payload.ref?.replace(/^refs\/heads\//, '') || null;
        addCandidate(candidates, event.payload.head, branch, null);
      }
    }
    if (pulls.ok && Array.isArray(pulls.data)) {
      for (const pull of pulls.data) {
        if (!pull.head?.sha) continue;
        addCandidate(candidates, pull.head.sha, pull.head.ref || null, null);
      }
    }
    for (const fetch of branchFetches) {
      if (!fetch.response.ok || !Array.isArray(fetch.response.data)) continue;
      for (const item of fetch.response.data) {
        addCandidate(candidates, item.sha, fetch.branch, item);
      }
    }

    let detailFailures = 0;
    const commits = [];
    for (const [sha, candidate] of candidates) {
      const detail = await api(fetchImpl, `${basePath}/commits/${encodeURIComponent(sha)}`, authorization);
      const payload = detail.ok ? detail.data : candidate.payload;
      if (!detail.ok) detailFailures += 1;
      if (payload) commits.push(commitRecord(payload, repository, fullName, candidate.branch, tasks));
    }
    commits.sort((left, right) => (right.committedAt || '').localeCompare(left.committedAt || ''));
    const branchWarnings = [];
    if (requestedBranches.length && !branchCatalog.ok) branchWarnings.push('branch list unavailable');
    if (branchCatalog.truncated) branchWarnings.push('branch list exceeded 500 entries');
    if (branchSelection.unmatched.length) branchWarnings.push(`branch not found: ${branchSelection.unmatched.join(', ')}`);
    if (matchedBranches.length > MAX_TASK_BRANCHES) branchWarnings.push(`branch limit exceeded: ${matchedBranches.length}/${MAX_TASK_BRANCHES}`);
    for (const fetch of branchFetches.filter(item => !item.response.ok)) {
      branchWarnings.push(`branch activity unavailable: ${fetch.branch}`);
    }
    const status = failedSources.length || detailFailures || branchWarnings.length
      ? 'partial'
      : commits.length ? 'ok' : 'no-activity';
    result.repositories.push({
      name: metadata.data.name || repository.name || parsed.repo,
      project: repository.project || null,
      source: repository.source || 'notion',
      status,
      defaultBranch,
      branch: defaultBranch,
      remote: metadata.data.html_url || `https://github.com/${fullName}`,
      latestCommitAt: commits[0]?.committedAt || null,
      lastFetchedAt,
      commitCount: commits.length,
      mappedCommitCount: commits.filter(commit => commit.workItemId).length,
      ...(requestedBranches.length ? {
        requestedBranches,
        matchedBranches: limitedBranches,
        unmatchedBranches: branchSelection.unmatched,
        branchMatches: branchSelection.matches
          .filter(match => limitedBranches.includes(match.actual))
          .map(({ requested, actual, matchType }) => ({ requested, actual, matchType })),
      } : {}),
    });
    result.commits.push(...commits);
    if (status === 'partial') {
      result.errors.push(`GitHub ${fullName}: partial activity data`);
      result.errors.push(...branchWarnings.map(warning => `GitHub ${fullName}: ${warning}`));
    }
  }
  result.commits.sort((left, right) => (right.committedAt || '').localeCompare(left.committedAt || ''));
  return result;
}

